#include <fcntl.h>
#include <stdio.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>

int main(int argc, char **argv) {
    int fd = open(argv[1], O_RDONLY);
    struct stat st;
    fstat(fd, &st);                       /* file size in st.st_size */
    unsigned char *p = mmap(NULL, st.st_size, PROT_READ,
                            MAP_PRIVATE, fd, 0);
    if (p == MAP_FAILED) { perror("mmap"); return 1; }
    close(fd);                            /* the mapping stays valid */

    unsigned long sum = 0;
    for (off_t i = 0; i < st.st_size; i++)
        sum += p[i];                      /* page faults happen here */
    printf("%lu\n", sum);
    munmap(p, st.st_size);
    return 0;
}
